students_tuple = ('Alice', 'Bob', 'Charlie', 'Diana', 'Eve')
enrolled = {'Alice', 'Charlie', 'Eve'}

def find_unenrolled(t, s):
    unenrolled = set()
    for name in t:
        if name not in s:
            unenrolled.add(name)
    return unenrolled

print(find_unenrolled(students_tuple, enrolled))  # Output: {'Bob', 'Diana'}

def courses_with_many_students(data):
    result = set()
    for entry in data:
        code = entry[0]
        ids = entry[1]
        seen = set()
        for sid in ids:
            if sid not in seen:
                seen.add(sid)
                count = len(seen)
        if len(seen) > 3:
            result.add(code)
    return result

# Example
