def extract_valid_ys(coords, forbidden_x):
    valid_ys = set()
    for pair in coords:
        x, y = pair
        if x not in forbidden_x:
            valid_ys.add(y)
    return valid_ys

# Example
print(extract_valid_ys(((1, 10), (2, 20), (1, 10), (3, 30)), {2}))  # Output: {10, 30}
